starterCode.css:
body { font-family: system-ui, sans-serif; padding: 24px; background: #f5f7fb; }
form { display: grid; gap: 16px; max-width: 520px; margin: auto; }
fieldset { display: grid; gap: 10px; border: 1px solid #cfd8e3; border-radius: 8px; padding: 16px; }
input, textarea, button { padding: 8px 10px; }
